#include <iostream>
using namespace std;

bool isRelatedTo7(int x) {
    // 判断是否能被 7 整除
    if (x % 7 == 0) return true;
    // 判断某一位是否为 7
    int t = x;
    while (t > 0) {
        if (t % 10 == 7) return true;
        t /= 10;
    }
    return false;
}

int main() {
    int n;
    cin >> n;
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        if (!isRelatedTo7(i)) {
            sum += i * i;
        }
    }
    cout << sum << endl;
    return 0;
}

